steps.run:
case "$PRESSURE_OBSERVATION_ONLY" in
  true) selection=(--pressure-observation-only) ;;
  false) selection=() ;;
  *) exit 2 ;;
esac
python3 -B tools/replay_rust_wasi_http_forbidden_runtime.py \
  --original-artifact "$RUNNER_TEMP/rust-http-original" \
  --native-products "$RUNNER_TEMP/rust-http-native" \
  --output "$RUNNER_TEMP/rust-http-node-replay" "${selection[@]}"
